Object.assign(dunitPlannerPresentationText.pt,{dunitGoalTip:'Registre primeiro no D-Unit Codex os conjuntos e condições que você já concluiu. Assim, a rota considera seu progresso atual.',dunitGoToCodex:'Ir para o D-Unit Codex',dunitHomeSets:'conjuntos D-Unit',dunitHomeConditions:'condições cadastradas',dunitWhatIs:'O que é o D-Unit?',dunitWhatIsText:'O D-Unit, também chamado de Sistema de União, permite obter bônus adicionais ao cumprir condições específicas de diferentes conjuntos de Digimons. Essas condições podem envolver obtenção de Digimons, níveis, transcendência e outros requisitos definidos por cada conjunto.',dunitImportanceText:'Cada condição concluída concede o bônus indicado pelo conjunto. Por isso, acompanhar seu progresso no D-Unit ajuda a identificar quais atributos você já possui e quais condições ainda podem ser concluídas para fortalecer seu personagem.',dunitHowToUse:'Como usar o D-Unit no Codex',dunitHowToUseText:'No D-Unit Codex você pode marcar as condições que já concluiu. Esse progresso é utilizado pelo planejador “Quero atingir um atributo” para considerar apenas os bônus adicionais que ainda podem ser obtidos.',dunitFlowRegister:'Registre suas condições concluídas',dunitFlowTarget:'Defina o atributo desejado',dunitFlowRoutes:'Consulte as rotas possíveis'})
Object.assign(dunitPlannerPresentationText.en,{dunitGoalTip:'First register in D-Unit Codex the sets and conditions you have already completed. This lets the route use your current progress.',dunitGoToCodex:'Go to D-Unit Codex',dunitHomeSets:'D-Unit sets',dunitHomeConditions:'registered conditions',dunitWhatIs:'What is D-Unit?',dunitWhatIsText:'D-Unit, also called the Union System, grants additional bonuses when you fulfill specific conditions from different Digimon sets. These conditions may involve obtaining Digimon, levels, transcendence, and other requirements defined by each set.',dunitImportanceText:'Each completed condition grants the bonus indicated by its set. Tracking your D-Unit progress therefore helps identify which attributes you already have and which conditions can still strengthen your character.',dunitHowToUse:'How to use D-Unit in Codex',dunitHowToUseText:'In D-Unit Codex, you can mark the conditions you have already completed. The “I want to reach an attribute” planner uses this progress to consider only additional bonuses that can still be obtained.',dunitFlowRegister:'Record completed conditions',dunitFlowTarget:'Set the desired attribute',dunitFlowRoutes:'Review possible routes'})
Object.assign(dunitPlannerPresentationText.es,{dunitGoalTip:'Primero registra en D-Unit Codex los conjuntos y condiciones que ya completaste. Así, la ruta considera tu progreso actual.',dunitGoToCodex:'Ir a D-Unit Codex',dunitHomeSets:'conjuntos D-Unit',dunitHomeConditions:'condiciones registradas',dunitWhatIs:'¿Qué es D-Unit?',dunitWhatIsText:'D-Unit, también llamado Sistema de Unión, permite obtener bonos adicionales al cumplir condiciones específicas de diferentes conjuntos de Digimon. Estas condiciones pueden involucrar la obtención de Digimon, niveles, trascendencia y otros requisitos definidos por cada conjunto.',dunitImportanceText:'Cada condición completada concede el bono indicado por el conjunto. Por eso, seguir tu progreso en D-Unit ayuda a identificar qué atributos ya tienes y qué condiciones aún pueden completarse para fortalecer tu personaje.',dunitHowToUse:'Cómo usar D-Unit en Codex',dunitHowToUseText:'En D-Unit Codex puedes marcar las condiciones que ya completaste. El planificador “Quiero alcanzar un atributo” usa este progreso para considerar solo los bonos adicionales que aún pueden obtenerse.',dunitFlowRegister:'Registra tus condiciones completadas',dunitFlowTarget:'Define el atributo deseado',dunitFlowRoutes:'Consulta las rutas posibles'})
Object.assign(dunitPlannerPresentationText.ko,{dunitGoalTip:'먼저 D-Unit Codex에서 이미 완료한 세트와 조건을 등록하세요. 그러면 경로가 현재 진행도를 반영합니다.',dunitGoToCodex:'D-Unit Codex로 이동',dunitHomeSets:'D-Unit 세트',dunitHomeConditions:'등록된 조건',dunitWhatIs:'D-Unit이란?',dunitWhatIsText:'D-Unit은 유니온 시스템이라고도 하며, 서로 다른 디지몬 세트의 특정 조건을 완료하면 추가 보너스를 얻을 수 있습니다. 조건에는 디지몬 획득, 레벨, 초월 및 각 세트에 정의된 기타 요구 사항이 포함될 수 있습니다.',dunitImportanceText:'완료한 각 조건은 세트에 표시된 보너스를 제공합니다. D-Unit 진행도를 추적하면 이미 보유한 속성과 캐릭터를 강화하기 위해 아직 완료할 수 있는 조건을 파악할 수 있습니다.',dunitHowToUse:'Codex에서 D-Unit 사용하기',dunitHowToUseText:'D-Unit Codex에서 이미 완료한 조건을 표시할 수 있습니다. “속성 목표” 플래너는 이 진행도를 사용하여 아직 획득할 수 있는 추가 보너스만 고려합니다.',dunitFlowRegister:'완료한 조건 등록',dunitFlowTarget:'원하는 속성 설정',dunitFlowRoutes:'가능한 경로 확인'})

function App(){
 const [tab,setTab]=useState<Tab>('home'), [lang,setLang]=useState<Lang>(()=>stored('ladmo-lang','pt')), [sealStates,setSealStates]=useState<SealStateMap>(()=>readSealStates(localStorage)), [dunitProgress,setDunitProgress]=useState<DUnitProgressState>(()=>readDUnitProgress(localStorage)), [dunitInventory,setDunitInventory]=useState<DUnitInventory>(()=>readDUnitInventory(localStorage)), [ticketBudget,setTicketBudget]=useState(()=>stored('ladmo-tickets',500)), [openerBudget,setOpenerBudget]=useState(()=>stored('ladmo-openers',20)), [menu,setMenu]=useState(false),[mineMode,setMineMode]=useState<'seals'|'dunit'>('seals'),[progressMode,setProgressMode]=useState<'seals'|'dunit'>('seals'),[goalMode,setGoalMode]=useState<'seals'|'dunit'>('seals')
 const owned=toOwnedSeals(sealStates); const t:any=Object.assign({},translationGroups.copy[lang],translationGroups.extraCopy[lang],translationGroups.sourceCopy[lang],translationGroups.uiCopy[lang],translationGroups.sourceDetailCopy[lang],translationGroups.roundCopy[lang],translationGroups.dunitUpdateCopy[lang],translationGroups.buffDeckCopy[lang],translationGroups.ticketBudgetCopy[lang],translationGroups.equipmentCopy[lang],translationGroups.equipmentProgressionCopy[lang],dunitText[lang],dunitCostText[lang],dunitInventoryText[lang],dunitPlannerPresentationText[lang],{dunitRouteCandidate:dunitRouteCandidateText[lang],dunitCostUnverified:dunitCostUnverifiedText[lang]}); useEffect(()=>localStorage.setItem('ladmo-lang',JSON.stringify(lang)),[lang]); useEffect(()=>localStorage.setItem(sealStateKey,JSON.stringify(sealStates)),[sealStates]); useEffect(()=>localStorage.setItem(dUnitProgressKey,JSON.stringify(dunitProgress)),[dunitProgress]); useEffect(()=>localStorage.setItem(dUnitInventoryKey,JSON.stringify(dunitInventory)),[dunitInventory]); useEffect(()=>localStorage.setItem('ladmo-tickets',JSON.stringify(ticketBudget)),[ticketBudget]); useEffect(()=>localStorage.setItem('ladmo-openers',JSON.stringify(openerBudget)),[openerBudget])
 const go=(x:Tab)=>{setTab(x);setMenu(false);window.scrollTo({top:0,behavior:'smooth'})}; const state=(id:string)=>getSealState(sealStates,id); const qty=(id:string)=>state(id).quantity
 const patchState=(id:string,patch:Parameters<typeof updateSealState>[2])=>setSealStates(x=>updateSealState(x,id,patch)); const addRecommendation=(id:string,additionalQuantity:number)=>setSealStates(x=>addRecommendedQuantity(x,id,additionalQuantity)); const setQty=(id:string,quantity:number)=>patchState(id,{quantity:Math.max(0,quantity),hasSeal:quantity>0||state(id).hasSeal})
 const toggleDunit=(setId:string,conditionId:string,checked:boolean)=>setDunitProgress(value=>toggleDUnitCondition(value,setId,conditionId,checked)); const patchDunitInventory=(id:string,patch:Parameters<typeof updateDUnitInventory>[2])=>setDunitInventory(value=>updateDUnitInventory(value,id,patch)); const nav: [Tab,string,typeof BookOpen][]=[['codex',t.codex,BookOpen],['dunit',t.dunitCodex,BookOpen],['goal',t.goal,Calculator],['equipment',t.equipment,Swords],['buffDecks',t.buffDecks,GitBranch],['mine',t.mine,Heart],['progress',t.progress,Gauge],['learn',t.learn,CircleHelp],['updates',t.updates,BookOpen],['about',t.about,Lightbulb]]
 return <><header className="site-header"><button className="brand" onClick={()=>go('home')}><img src={avatarUrl}/><span>LADMO <b>SEAL</b><small>CODEX</small></span></button><nav className={menu?'show':''}>{nav.map(([id,label,Icon])=><button className={tab===id?'active':''} key={id} onClick={()=>go(id)}><Icon size={16}/>{label}</button>)}</nav><div className="header-actions"><select aria-label={t.languageLabel} value={lang} onChange={e=>setLang(e.target.value as Lang)}><option value="pt">PT-BR</option><option value="en">EN</option><option value="es">ES</option><option value="ko">KO / 한국어</option></select><button className="icon mobile" onClick={()=>setMenu(!menu)}>{menu?<X/>:<Menu/>}</button></div></header>
 <main>{tab==='home'&&<Home t={t} go={go} owned={owned}/>} {tab==='codex'&&<SealCodex t={t} lang={lang} state={state} patchState={patchState}/>} {tab==='dunit'&&<DUnitCodex t={t} progress={dunitProgress} toggle={toggleDunit}/>} {tab==='goal'&&<><div className="subtabs"><button className={goalMode==='seals'?'active':''} onClick={()=>setGoalMode('seals')}>{t.sealMaster}</button><button className={goalMode==='dunit'?'active':''} onClick={()=>setGoalMode('dunit')}>D-Unit</button></div>{goalMode==='seals'?<GoalPlanner t={t} lang={lang} state={state} go={go} addRecommendation={addRecommendation} ticketBudget={ticketBudget}/>:<DUnitGoalPlanner t={t} progress={dunitProgress} toggle={toggleDunit} playerState={dUnitPlayerStateFromInventory(dunitInventory)}/>}</>} {tab==='equipment'&&<Equipment t={t}/>} {tab==='buffDecks'&&<BuffDeckProgression t={t}/>} {tab==='mine'&&<><div className="subtabs"><button className={mineMode==='seals'?'active':''} onClick={()=>setMineMode('seals')}>{t.mine}</button><button className={mineMode==='dunit'?'active':''} onClick={()=>setMineMode('dunit')}>{t.myDUnit}</button></div>{mineMode==='seals'?<MySeals t={t} lang={lang} states={sealStates} state={state} patchState={patchState}/>:<MyDUnit t={t} progress={dunitProgress} toggle={toggleDunit} inventory={dunitInventory} updateInventory={patchDunitInventory}/>}</>} {tab==='progress'&&<><div className="subtabs"><button className={progressMode==='seals'?'active':''} onClick={()=>setProgressMode('seals')}>{t.sealMaster}</button><button className={progressMode==='dunit'?'active':''} onClick={()=>setProgressMode('dunit')}>D-Unit</button></div>{progressMode==='seals'?<Progress t={t} owned={owned}/>:<DUnitProgressPage t={t} progress={dunitProgress}/>}</>} {tab==='compare'&&<Compare t={t} lang={lang}/>} {tab==='learn'&&<HowItWorks t={t}/>} {tab==='updates'&&<Updates t={t}/>} {tab==='about'&&<About t={t} reset={()=>{if(!confirmAndClearLadmoStorage(localStorage,window.confirm,t.resetLocalDataConfirmation))return;setSealStates({});setDunitProgress({});setDunitInventory({});setTicketBudget(500);setOpenerBudget(20)}}/>}</main>
 <footer><div className="footer-brand"><img src={avatarUrl}/>NadaNerd Live</div><span>{t.official} {t.footerDisclaimer}</span><div><a href="https://www.youtube.com/@nadanerdlive" target="_blank">YouTube <ExternalLink size={13}/></a><a href="https://www.twitch.tv/nadanerd" target="_blank">Twitch <ExternalLink size={13}/></a></div></footer></>
}
export default App

